    up = down = 0

    # A T pointing up has its stem above its three-cell bar.
    # A T pointing down has its stem below its bar.
    for r in range(h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 2
                    and all(grid[r + 1][x] == 2 for x in range(c - 1, c + 2))):
                up += 1
            if (all(grid[r][x] == 2 for x in range(c - 1, c + 2))
                    and grid[r + 1][c] == 2):
                down += 1

    out = [[0] * 6 for _ in range(3)]
    positions = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for count, color, offset in [(up, 3, 0), (down, 1, 3)]:
        for r, c in positions[:min(count, 4)]:
            out[r][offset + c] = color
    return out
